def stream_rows(resource, transform):
    processing_failed = False
    try:
        while True:
            try:
                row = resource.read_next()
                if row is None:
                    break
                value = transform(row)
            except BaseException:
                processing_failed = True
                raise
            yield value
    finally:
        if processing_failed:
            # Cleanup must not replace an active read or transform error.
            try:
                resource.close()
            except BaseException:
                pass
        else:
            resource.close()
